// Folder-backed exFAT disk with optional session-only copy-on-write. Descriptor generated by virtual_exfat.py.
#include <algorithm>
#include <memory>
#include <sys/time.h>
#include <cstdio>
#include <unordered_set>

class VirtualDisk {
    struct Source {
        std::string path;
        uint64_t offset=0,size=0,dev=0,ino=0,mtime=0,ctime=0,allocated=0;
        bool directory=false;
        int fd=-1;
        uint64_t used=0;
    };
    std::vector<Source> sources;
    std::vector<size_t> extents;
    std::vector<uint8_t> metadata;
    uint64_t length=0,clock=0;
    // Only changed sectors occupy space. Neither source files nor descriptor are written.
    FILE* overlay=nullptr;
    std::unordered_set<uint64_t> changed;
    static constexpr uint64_t overlay_limit=512ULL*1024*1024;

    size_t opened=0;
    std::chrono::steady_clock::time_point checked{};
    static uint64_t integer(std::istream& in,unsigned n) {
        uint64_t value=0;
        for(unsigned i=0;i<n;i++) { int c=in.get(); if(c==EOF) fail("Descriptor virtual incompleto"); value|=uint64_t(uint8_t(c))<<(i*8); }
        return value;
    }
    static uint64_t ns(const timespec& t) { return uint64_t(t.tv_sec)*1000000000+uint64_t(t.tv_nsec); }
    static bool matches(const Source& s,const struct stat& st) {
        return (s.directory?S_ISDIR(st.st_mode):S_ISREG(st.st_mode)) &&
            uint64_t(st.st_dev)==s.dev && uint64_t(st.st_ino)==s.ino &&
            uint64_t(st.st_size)==s.size && ns(st.st_mtim)==s.mtime && ns(st.st_ctim)==s.ctime;
    }
    void verify(Source& s) {
        struct stat st{};
        if(lstat(s.path.c_str(),&st)<0 || !matches(s,st))
            fail("El origen ha cambiado; servidor detenido: "+s.path);
        if(s.fd>=0 && (fstat(s.fd,&st)<0 || !matches(s,st)))
            fail("Un archivo abierto ha cambiado: "+s.path);
    }
    int file(Source& s) {
        verify(s);
        if(s.fd<0) {
            if(opened>=64) {
                Source* oldest=nullptr;
                for(auto& item:sources) if(item.fd>=0 && (!oldest || item.used<oldest->used)) oldest=&item;
                if(oldest) { close(oldest->fd); oldest->fd=-1; --opened; }
            }
            s.fd=open(s.path.c_str(),O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK);
            if(s.fd<0) syserr("Abrir archivo "+s.path);
            ++opened;
            verify(s);
            if(flock(s.fd,LOCK_SH|LOCK_NB)<0) syserr("Reservar archivo "+s.path);
        }
        s.used=++clock;
        return s.fd;
    }
public:
    explicit VirtualDisk(const std::string& path,bool writable=false) {
        std::ifstream in(path,std::ios::binary);
        char magic[8]; in.read(magic,8);
        if(!in || std::memcmp(magic,"UDPVF001",8)) fail("Descriptor virtual inválido");
        length=integer(in,8); uint64_t meta=integer(in,8),count=integer(in,4);
        if(length<512 || length%512 || length/512>UINT32_MAX || meta>128*1024*1024 || meta>length || count>20000)
            fail("Límites de disco virtual inválidos");
        metadata.resize(meta); in.read(reinterpret_cast<char*>(metadata.data()),meta);
        if(!in) fail("Metadatos virtuales incompletos");
        sources.reserve(count);
        for(uint64_t i=0;i<count;i++) {
            Source s; s.directory=integer(in,1); s.offset=integer(in,8); s.size=integer(in,8);
            s.dev=integer(in,8); s.ino=integer(in,8); s.mtime=integer(in,8); s.ctime=integer(in,8); s.allocated=integer(in,8);
            unsigned n=integer(in,4);
            if(!n || n>4096) fail("Ruta virtual inválida");
            s.path.resize(n); in.read(s.path.data(),n);
            if(!in || s.path.front()!='/' || s.path.find('\0')!=std::string::npos) fail("Ruta virtual inválida");
            if(!s.directory && s.size && (s.offset<meta || s.offset>length || s.size>length-s.offset || s.allocated<s.size || s.allocated>length-s.offset))
                fail("Extensión virtual fuera de rango");
            sources.push_back(std::move(s));
            if(!sources.back().directory && sources.back().size) extents.push_back(i);
        }
        std::sort(extents.begin(),extents.end(),[&](size_t a,size_t b){return sources[a].offset<sources[b].offset;});
        uint64_t end=meta;
        for(auto i:extents) {
            if(sources[i].offset<end) fail("Extensiones virtuales solapadas");
            end=sources[i].offset+sources[i].allocated;
        }
        validate(true);
        if(writable) {
            overlay=std::tmpfile();
            if(!overlay) syserr("Crear capa temporal de escritura");
            if(fcntl(fileno(overlay),F_SETFD,FD_CLOEXEC)<0) {
                int saved=errno; std::fclose(overlay); overlay=nullptr; errno=saved;
                syserr("Proteger descriptor temporal");
            }
        }
    }
    ~VirtualDisk() { if(overlay) std::fclose(overlay); for(auto& s:sources) if(s.fd>=0) close(s.fd); }
    uint64_t bytes() const { return length; }
    void validate(bool force=false) {
        auto now=std::chrono::steady_clock::now();
        if(!force && now-checked<std::chrono::seconds(1)) return;
        for(auto& s:sources) verify(s);
        checked=now;
    }
    bool read(uint8_t* data,size_t size,uint64_t offset) {
        if(offset>length || size>length-offset) return false;
        std::memset(data,0,size);
        if(offset<metadata.size()) {
            auto n=std::min(size,metadata.size()-size_t(offset));
            std::memcpy(data,metadata.data()+offset,n);
        }
        auto first=std::lower_bound(extents.begin(),extents.end(),offset,[&](size_t i,uint64_t off){
            return sources[i].offset+sources[i].size<=off;
        });
        for(auto it=first;it!=extents.end();++it) {
            auto& s=sources[*it];
            if(s.offset>=offset+size) break;
            uint64_t start=std::max(offset,s.offset),end=std::min(offset+size,s.offset+s.size);
            if(start<end) {
                if(!exact_io(file(s),data+(start-offset),end-start,start-s.offset,false)) fail("No se pudo leer "+s.path);
                verify(s);
            }
        }
        if(overlay && size) {
            uint64_t end=offset+size;
            for(uint64_t sector=offset/512;sector<=(end-1)/512;++sector) {
                if(!changed.count(sector)) continue;
                uint64_t start=std::max(offset,sector*512),stop=std::min(end,(sector+1)*512);
                if(!exact_io(fileno(overlay),data+(start-offset),stop-start,start,false)) return false;
            }
        }
        return true;
    }
    int write(uint8_t* data,size_t size,uint64_t offset) {
        if(!overlay) return -EROFS;
        if(offset%512 || size%512 || offset>length || size>length-offset) return -EINVAL;
        size_t added=0;
        for(uint64_t sector=offset/512;sector<(offset+size)/512;++sector)
            if(!changed.count(sector)) ++added;
        if(changed.size()+added>overlay_limit/512) return -ENOSPC;
        // Reserve before IO: a successful response always has a readable sector index.
        changed.reserve(changed.size()+added);
        if(!exact_io(fileno(overlay),data,size,offset,true)) return -(errno?errno:EIO);
        if(fdatasync(fileno(overlay))<0) return -errno;
        for(uint64_t sector=offset/512;sector<(offset+size)/512;++sector) changed.insert(sector);
        return 0;
    }
};

class Traffic {
    bool enabled;
    uint64_t rx=0,tx=0,rb=0,tb=0,omitted=0;
    std::vector<std::string> samples;
    std::chrono::steady_clock::time_point last=std::chrono::steady_clock::now();
public:
    explicit Traffic(bool enabled):enabled(enabled) {}
    ~Traffic() { flush(true); }
    void packet(bool sent,const uint8_t* p,size_t n,const sockaddr_in& peer) {
        if(!enabled) return;
        if(sent) { ++tx; tb+=n; } else { ++rx; rb+=n; }
        if(samples.size()>=40) { ++omitted; return; }
        char ip[INET_ADDRSTRLEN]; inet_ntop(AF_INET,&peer.sin_addr,ip,sizeof(ip));
        unsigned h=n>=2?u16(p):0;
        std::ostringstream s;
        s<<"[\""<<(sent?"TX":"RX")<<"\",\""<<ip<<":"<<ntohs(peer.sin_port)<<"\","<<n<<",";
        if(n>=2) s<<(h&31)<<","<<((h>>5)&7)<<","<<(h>>8); else s<<"-1,0,0";
        s<<"]"; samples.push_back(s.str());
    }
    void flush(bool force=false) {
        if(!enabled) return;
        auto now=std::chrono::steady_clock::now();
        if(!force && now-last<std::chrono::milliseconds(250)) return;
        std::cout<<"@traffic {\"rx\":"<<rx<<",\"tx\":"<<tx<<",\"rx_bytes\":"<<rb<<",\"tx_bytes\":"<<tb<<",\"omitted\":"<<omitted<<",\"samples\":[";
        bool comma=false;
        for(auto& s:samples) { if(comma) std::cout<<","; std::cout<<s; comma=true; }
        std::cout<<"]}\n";
        samples.clear(); last=now;
    }
};
